FIX={"\t":"\\t","\x08":"\\b","\r":"\\r","\x0c":"\\f","\x07":"\\a","\x0b":"\\v","\n":" "}
def fx(v):
    if isinstance(v,str):
        for a,b in FIX.items(): v=v.replace(a,b)
        return v
    return v
R=[{k:fx(v) for k,v in x.items()} for x in R]
